const r=await tools.image_gen__imagegen({referenced_image_paths:["E:/githome/kong-rpg/assets/motion-v12/nezha-reference.png"],transparent_background:true,prompt:"Production sprite-animation atlas, edit/extend the approved reference Nezha character, same side-view facing RIGHT, same gold armor, black topknot, teal trousers and red silk. EXACT grid FOUR COLUMNS by FIVE ROWS, 20 isolated full-body frames, generous transparent gutters, each equal cell and SAME foot baseline and body scale; entire fire-tip SPEAR stays inside each cell. Genuine transparent RGBA. Preserve readable pixel clusters and existing costume, no background, text, labels, panels, magic rings, fire explosion or motion streak. Row 1: four anatomically coherent RUN cycle keyframes (contact, down, passing, up), spear carried angled forward, alternate feet and bending knees, not a sliding idle. Row 2: spear JAB sequence: coil with spear tip withdrawn, clearly extended thrust, follow-through, return to guard. Row 3: spear SWEEP sequence: wind spear to shoulder behind, short diagonal sweep forward, finish across front, return to guard. Row 4: HEAVY THRUST sequence: crouched braced anticipation, powerful long lunge with straight spear pointing RIGHT, forward finish, balanced recovery. Row 5: rising jump with folded rear leg, falling with feet prepared to land, clear backward HURT recoil holding spear safely away, neutral guard idle. Hands always hold the shaft coherently; no detached hands, extra limbs or duplicated weapon. Attack anticipation must NOT look like extended impact. All spear tips and body parts uncropped. Broad clear poses rather than filigree. This is an actual game-size animation asset, not concept art."});
store("motion_nezha",r);generatedImage(r);text({keys:Object.keys(r),hint:r.output_hint});

// @exec: {"yield_time_ms": 120000, "max_output_tokens": 1000}
const r=await tools.image_gen__imagegen({referenced_image_paths:["E:/githome/kong-rpg/assets/motion-v12/erlang-reference.png"],transparent_background:true,prompt:"Create a production animation atlas extending this approved Erlang Shen game sprite. Keep same identity, teal-gold lamellar armor, long white mantle, third-eye headpiece, side-view facing RIGHT, the same long three-pointed double-edged poleblade. EXACT FOUR COLUMNS x FIVE ROWS = TWENTY full-body sprites in equal cells, transparent gutters separating every frame, same body proportions, root and foot baseline. Make weapon motion anatomically coherent with both hands gripping one shaft; NO bow or arrow anywhere. Large readable pixel clusters, game pixel art, no labels, text, scenery, panel, effects, slash glows or afterimages. ROW 1 four RUN cycle frames (contact/down/passing/up), knees and alternating feet genuinely change, cape follows inertia, poleblade angled forward. ROW 2 four phases of short FORWARD POLEBLADE CUT: preparation with blade withdrawn, active forward cut, follow-through, guard recovery. ROW 3 four phases of RISING DIAGONAL CUT: pull blade low to rear, cut diagonally up/right, finish, balanced return. ROW 4 four phases of HEAVY OVERHEAD CLEAVE: blade lifted above/back, clear downward strike in front, low finish, guard recovery. ROW 5 rising jump, falling landing preparation, backward HURT recoil, neutral idle. Every pose has distinct weight and planted supporting foot when grounded. Anticipation is withdrawn, contact extends forward, recovery pulls back. Maintain body size between every frame. Keep ALL blade tips, feet and mantle inside individual cells; no frame touching another. Genuine transparent RGBA."});
store("motion_erlang",r);generatedImage(r);text({hint:r.output_hint});

// @exec: {"yield_time_ms": 120000, "max_output_tokens": 700}
const r=await tools.image_gen__imagegen({referenced_image_paths:["E:/githome/kong-rpg/assets/motion-v12/cloud-reference.png"],transparent_background:true,prompt:"Production PIXEL game ENEMY ANIMATION atlas. Reference shows FIVE different approved cloud-court enemies left to right. Preserve their five identities, outfits, weapons and cool white-blue armor, NOT new monsters. Arrange exactly FIVE ROWS (one reference identity per row, same order) by SIX COLUMNS. Thirty separate full-body sprites, all facing RIGHT with generous TRANSPARENT gutters and exact same foot baseline/body scale within a row. Col1 walking contact foot, col2 walking passing foot, col3 ANTICIPATION pulling weapon back, col4 actual RELEASE in front, col5 balanced RECOVERY pulling weapon back, col6 HIT RECOIL backwards. No scenery, panels, words, HUD, magical effects, slash streaks or large shadows. Row1 halberd soldier performs close halberd slash; row2 ranged robed archer/caster aims then releases a clear forward shot; row3 round-shield soldier crouches and readies shield then a short shield-led charge; row4 taller halberd captain performs a heavier polearm slash; row5 feathered commander raises and releases a forward wind spell. Preserve the anatomy of each humanoid and planted supporting foot, hand/weapon grip, continuous readable motion. Feet and all polearm tips must fit within each cell, no touching adjacent characters. Clean large pixel clusters and restrained shading suited to 50-75px in-game body height. Genuine transparent RGBA, not a conceptual illustration."});
store("motion_cloud",r);generatedImage(r);text({hint:r.output_hint});

// @exec: {"yield_time_ms": 120000, "max_output_tokens": 1200}
const jobs=[
["underworld","E:/githome/kong-rpg/assets/motion-v12/underworld-reference.png","underworld ghost court: row1 chain-hook guard pulls hook back then hooks forward; row2 green lantern caster raises lantern then extends hand to cast; row3 cage-shield gaoler braces then surges shield-first; row4 tall chained jailer swings large hook; row5 dark magistrate readies then points scroll judgement. Keep each original headwear and lantern/cage/hook/scroll. No modern weapons."],
["water","E:/githome/kong-rpg/assets/motion-v12/water-reference.png","undersea monsters: row1 red shrimp spearman two legs and antennae, thrusts spear; row2 purple clam caster keeps hinged shell and pearls, shell closes in anticipation then opens at release; row3 blue scaled fish guard keeps shield and curved blade, crouches then shield rush; row4 red giant lobster champion has TWO claws and multiple supporting legs, prepares then snaps forward; row5 teal finned serpent mage coils then lunges head forward to spit, NEVER gains humanoid legs. Keep each reference anatomy precisely."]
];
const results=await Promise.allSettled(jobs.map(async([name,ref,details])=>{
const r=await tools.image_gen__imagegen({referenced_image_paths:[ref],transparent_background:true,prompt:"Production sprite animation atlas based on these FIVE approved enemy silhouettes, read left-to-right. "+details+" Exactly FIVE ROWS by SIX COLUMNS, one identity per row in reference order, all side-view facing RIGHT. Col1 walking/locomotion contact, col2 passing/alternate supporting feet (or second coil/shell locomotion state for nonhuman), col3 WITHDRAWN anticipation, col4 actual forward RELEASE, col5 return to guard RECOVERY, col6 backward HIT REACTION. Entire anatomy, held weapons and feet inside each cell with large transparent gutters, same root, proportions, costume and palette per row. Hands grip weapons coherently. All 30 poses distinct but same character within each row. Clean broad pixel-art clusters, limited colors, useful at 50-75px body height. Genuine transparent RGBA. NO backdrop or haze, effects, labels, poster layout, glow clouds or changing creature anatomy. Not concept art."});store("motion_"+name,r);generatedImage(r);text({name,hint:r.output_hint});return name;
}));text(results.map(x=>({status:x.status,value:x.value,reason:String(x.reason||"")})));

// @exec: {"yield_time_ms": 120000, "max_output_tokens": 1000}
const jobs=[
["dragon","E:/githome/kong-rpg/assets/motion-v12/dragon-reference.png","Dragon Palace sea court: row1 teal aquatic halberd soldier makes a short polearm cut; row2 blue-white robed sea mage raises then extends a pearl scepter; row3 teal crab guard braces its shield/claw then a short rush; row4 tall GOLD armored crab general winds up then snaps/strikes with golden claws; row5 blue-white dragon priest raises then unfurls a ritual scroll forward. Preserve sea-creature anatomy, fins, crab claws, and the reference gold/teal/blue-white hierarchy."],
["heaven","E:/githome/kong-rpg/assets/motion-v12/heaven-reference.png","Heavenly court: row1 gold-black halberd guard winds up then slashes; row2 blue-gold ritual mage raises scepter then extends free hand; row3 red-gold tower shield guard braces then shield-rushes; row4 tall white-plumed gold captain raises then strikes with his round shield/polearm; row5 imposing gold-red rectangular-shield commander raises curved sword then chops forward. Keep all armor, crests, cloaks and shield shapes from the reference. No firearms, modern rifles, guns or cannons."]
];
const results=await Promise.allSettled(jobs.map(async([name,ref,details])=>{const r=await tools.image_gen__imagegen({referenced_image_paths:[ref],transparent_background:true,prompt:"A production PIXEL ART animation atlas extending these FIVE existing enemy sprites in reference order. "+details+" EXACT FIVE ROWS x SIX COLUMNS, 30 full-body isolated poses. Every character faces RIGHT. Each row is ONE identity with unchanged anatomy, proportions, costume and palette; six columns show: 1 walking contact, 2 walking passing/supporting-leg alternate, 3 clearly withdrawn ANTICIPATION, 4 active forward RELEASE, 5 return to guard RECOVERY, 6 backward HIT RECOIL. Balanced weight and continuous hand/weapon grip. Very generous transparent gutters; complete feet, weapons and tails fit inside cells, never touch neighbors. Genuine transparent RGBA; no backdrop, haze, text, labels, panels, large magic effects or afterimages. Clean large pixel clusters, restrained shading and readable silhouettes at 50-75px body height. For nonhuman crab, animate its existing limbs/claws, never turn it into a human. Animation game asset, not illustration."});store("motion_"+name,r);generatedImage(r);text({name,hint:r.output_hint});return name;}));text(results.map(x=>({status:x.status,value:x.value,reason:String(x.reason||"")})));

// @exec: {"yield_time_ms": 120000, "max_output_tokens": 700}
const r=await tools.image_gen__imagegen({referenced_image_paths:["E:/githome/kong-rpg/assets/motion-v12/cloud-source.png"],transparent_background:true,prompt:"Edit this existing production 5-row x6-column sprite atlas. Change ONLY the ranged weapon held by the SIX characters in ROW TWO: replace the rifle-like shape with an unmistakable ANCIENT CHINESE WOODEN CROSSBOW, with broad curved bow limbs clearly projecting above and below the horizontal wooden stock, visible taut bowstring and small arrow, no metal gun barrel or rifle butt. Keep exactly 30 sprites and their current layout, size, positions, body/face/robe/palette and facing RIGHT. Row-two col3 readies/aims crossbow, col4 releases its string, col5 lowers/recover, col6 recoils while holding it; col1/2 carry it down. All other four rows remain visually unchanged. Genuine transparent RGBA, REMOVE any backdrop RGB haze from visible alpha; no added effects, labels, text or shadows. Maintain generous empty gutters and clean readable pixel clusters. Crossbow, not a modern firearm."});
store("motion_cloud_final",r);generatedImage(r);text({hint:r.output_hint});

